use crate::aap::caps::state_read;

struct Node;

/// Keys in the 'subscriptions' store under which the subscription list may
/// live, tried in order. The store cannot be enumerated, so the node can only
/// ask about keys it already knows.
const KEYS: &[&str] = &["urls", "subscriptions", "feeds"];

fn looks_like_url(s: &str) -> bool {
    let lower = s.to_ascii_lowercase();
    (lower.starts_with("https://") || lower.starts_with("http://"))
        && s.len() > "http://".len()
        && !s.chars().any(|c| c.is_whitespace() || c.is_control())
}

fn push_unique(out: &mut Vec<String>, candidate: &str) {
    let c = candidate.trim();
    if looks_like_url(c) && !out.iter().any(|u| u == c) {
        out.push(c.to_string());
    }
}

/// Read four hex digits starting at `i`.
fn hex4(chars: &[char], i: usize) -> Option<u32> {
    if i + 4 > chars.len() {
        return None;
    }
    let s: String = chars[i..i + 4].iter().collect();
    u32::from_str_radix(&s, 16).ok()
}

/// Extract every JSON string literal from `text`, with escapes decoded.
/// Tolerant: malformed input yields whatever strings could be recovered.
fn json_strings(text: &str) -> Vec<String> {
    let chars: Vec<char> = text.chars().collect();
    let mut out = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] != '"' {
            i += 1;
            continue;
        }
        i += 1;
        let mut s = String::new();
        let mut closed = false;
        while i < chars.len() {
            let c = chars[i];
            if c == '"' {
                closed = true;
                i += 1;
                break;
            }
            if c == '\\' && i + 1 < chars.len() {
                let e = chars[i + 1];
                i += 2;
                match e {
                    '"' => s.push('"'),
                    '\\' => s.push('\\'),
                    '/' => s.push('/'),
                    'b' => s.push('\u{8}'),
                    'f' => s.push('\u{c}'),
                    'n' => s.push('\n'),
                    'r' => s.push('\r'),
                    't' => s.push('\t'),
                    'u' => {
                        if let Some(hi) = hex4(&chars, i) {
                            i += 4;
                            let mut code = hi;
                            if (0xD800..0xDC00).contains(&hi)
                                && i + 1 < chars.len()
                                && chars[i] == '\\'
                                && chars[i + 1] == 'u'
                            {
                                if let Some(lo) = hex4(&chars, i + 2) {
                                    if (0xDC00..0xE000).contains(&lo) {
                                        code = 0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00);
                                        i += 6;
                                    }
                                }
                            }
                            if let Some(ch) = char::from_u32(code) {
                                s.push(ch);
                            }
                        }
                    }
                    other => s.push(other),
                }
                continue;
            }
            s.push(c);
            i += 1;
        }
        if closed {
            out.push(s);
        }
    }
    out
}

/// Parse a stored subscription value: either JSON (an array of URLs, or an
/// object containing them) or plain text with one URL per line / separated by
/// commas or whitespace, `#` starting a comment.
fn parse_subscriptions(value: &str) -> Vec<String> {
    let mut urls = Vec::new();
    let trimmed = value.trim();
    if trimmed.starts_with('[') || trimmed.starts_with('{') || trimmed.starts_with('"') {
        for s in json_strings(trimmed) {
            push_unique(&mut urls, &s);
        }
    } else {
        for line in trimmed.lines() {
            let line = match line.find('#') {
                Some(0) => continue,
                Some(pos) => &line[..pos],
                None => line,
            };
            for part in line.split(|c: char| c == ',' || c.is_whitespace()) {
                push_unique(&mut urls, part);
            }
        }
    }
    urls
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in KEYS {
            if let Some(value) = state_read::get(key) {
                let urls = parse_subscriptions(&value);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        // The contract requires `urls` to be present; with no subscriptions
        // in the store there is nothing honest to return, so fail the node
        // rather than emit an output that violates its `ensures`.
        panic!("LoadSubscriptions: no subscriptions found in the 'subscriptions' store");
    }
}

export!(Node);
